<script setup>
import {scopeLabel,statusLabel,quoteChecks} from '../view.js'
const props=defineProps({result:Object})
const memoryLabels={goal:'Цель',clarifications:'Уточнение',constraints:'Ограничение',terms:'Термин',source_days:'Дни источников'}
const reasonLabels={weak_context:'Ни один фрагмент не прошёл порог релевантности',model_unknown:'Модель не нашла достаточного подтверждения в переданном контексте',invalid_grounding:'Не прошла проверка цитат или идентификаторов источников',semantic_rejected:'Ни одно допустимое утверждение не прошло проверку смысла',invalid_verification:'Ответ проверяющей модели не прошёл проверку формата',duplicate_context_ids:'В контексте обнаружены повторяющиеся идентификаторы',grounded:'Опубликованные утверждения подтверждены',partially_grounded:'Опубликована только подтверждённая часть ответа',execution_error:'Ошибка выполнения запроса',request_failed:'Ошибка обработки запроса',confirmed_user_command:'Память изменена по вашей команде'}
function evidenceLabel(chunk){
 const anchor=chunk.anchor_chunk_id?' к '+chunk.anchor_chunk_id:''
 if(chunk.retrieval_role==='neighbor')return 'Соседний чанк'+anchor+' · cosine не вычислялся'
 if(chunk.retrieval_role==='lexical_context')return 'Дополнительный чанк по совпадениям слов'+anchor+' · cosine не вычислялся'
 return chunk.score==null?'Контекст · cosine не указан':'Опорный чанк · cosine '+Number(chunk.score).toFixed(3)
}
function decision(chunk){
 if(props.result.chunks?.some(selected=>selected.chunk_id===chunk.chunk_id)) return 'В контексте'
 if(Number(chunk.score ?? chunk.similarity ?? 0) < Number(props.result.settings?.threshold ?? -1)) return 'Ниже порога'
 return 'Вне конечного top-K'
}
</script>
<template><article v-if="result" class="answer panel" :class="result.status"><div class="row"><h3>{{ statusLabel(result.status) }}</h3><span class="badge">{{ result.status }}</span></div><p v-if="result.partial" class="clarification" role="status">Частичный ответ: опубликованы только подтверждённые утверждения. Исключено: {{ result.rejected_claims?.length || 0 }}. Полнота ответа не гарантируется.</p><p class="answer-text">{{ result.answer }}</p><details v-if="result.rejected_claims?.length"><summary>Отклонённые утверждения · {{ result.rejected_claims.length }}</summary><p class="tiny">Эти утверждения не входят в ответ и не подтверждены проверкой.</p><article v-for="claim in result.rejected_claims" :key="claim.index" class="citation"><p>{{ claim.text }}</p><span>{{ claim.status==='uncertain'?'Подтверждение не установлено':'Не подтверждено' }} · {{ claim.reason }}</span></article></details><details v-if="result.memory_update?.changes?.length" class="memory-changes"><summary>Память обновлена из вашего сообщения · {{ result.memory_update.changes.length }}</summary><ul><li v-for="(change,i) in result.memory_update.changes" :key="i"><b>{{ memoryLabels[change.field] || change.field }}:</b> {{ change.value }} <span v-if="change.action==='remove'">(удалено)</span><p v-if="change.evidence" class="tiny">Из сообщения: «{{ change.evidence }}»</p></li></ul></details><p v-if="result.memory_update?.warning" class="clarification">{{ result.memory_update.warning }}</p><p v-if="result.clarification" class="clarification">{{ result.clarification }}</p><p v-if="result.error" class="error">{{ typeof result.error==='string'?result.error:JSON.stringify(result.error) }}</p><p class="muted" v-if="result.reason">Причина: {{ reasonLabels[result.reason] || result.reason }}</p><div v-if="result.status!=='memory_updated'" class="checks"><span :class="{yes:quoteChecks(result).sources}">Источники {{ quoteChecks(result).sources?'✓':'—' }}</span><span :class="{yes:quoteChecks(result).exact}">Дословные цитаты {{ quoteChecks(result).exact?'✓':'—' }}</span><span :class="{yes:quoteChecks(result).semantic}">LLM-проверка: {{ result.validation?.semantic_status || 'не выполнена' }}</span></div><p v-if="result.status!=='memory_updated'" class="tiny">Совпадение текста проверяет сервер. Соответствие смысла оценивает отдельный LLM-verifier; это не доказательство истинности.</p><div v-if="result.sources?.length" class="citations"><article v-for="(source,i) in result.sources" :key="i" class="citation"><span class="eyebrow">УТВЕРЖДЕНИЕ {{ i+1 }}</span><p v-if="result.claims?.[i]?.text" class="claim-text">{{ result.claims[i].text }}</p><span class="eyebrow">ПОДТВЕРЖДАЮЩИЙ ИСТОЧНИК</span><b>{{ source.source }}</b><span>{{ source.section }}</span><code>{{ source.chunk_id }}</code><span v-if="['neighbor','lexical_context'].includes(source.retrieval_role)" class="badge">{{ evidenceLabel(source) }}</span><blockquote>{{ source.quote }}</blockquote></article></div><p v-else class="muted">{{ result.status==='memory_updated'?'Это запись вашей памяти задачи, не фактический ответ по источникам.':'Подтверждённых источников нет.' }}</p><details><summary>Поиск и проверка · {{ result.candidates?.length || 0 }} кандидатов → {{ result.chunks?.length || 0 }} опорных → {{ result.evidence_chunks?.length ?? result.chunks?.length ?? 0 }} доказательств</summary><p>Область: {{ scopeLabel(result.retrieval_scope) }}</p><p class="tiny">Порог cosine: {{ result.settings?.threshold ?? '—' }} · top-K до: {{ result.settings?.top_k_before ?? '—' }} · после: {{ result.settings?.top_k_after ?? '—' }}</p><div class="candidate" v-for="(chunk,i) in result.candidates || []" :key="i"><strong>{{ Number(chunk.score ?? chunk.similarity ?? 0).toFixed(3) }}</strong><span>{{ chunk.source }} · {{ chunk.section }}</span><code>{{ chunk.chunk_id }}</code><span class="badge">{{ decision(chunk) }}</span><details class="candidate-text"><summary>Текст найденного чанка</summary><p>{{ chunk.text }}</p><details v-if="chunk.boundary_context?.previous || chunk.boundary_context?.next"><summary>Соседние чанки: цитировать можно только включённые в evidence</summary><article v-for="side in ['previous','next']" :key="side" v-show="chunk.boundary_context?.[side]" class="citation"><span class="eyebrow">{{ side==='previous'?'ПРЕДЫДУЩИЙ':'СЛЕДУЮЩИЙ' }} ЧАНК · ПРОВЕРЬТЕ НАЛИЧИЕ В EVIDENCE</span><b>{{ chunk.boundary_context?.[side]?.source }}</b><span>{{ chunk.boundary_context?.[side]?.section }}</span><code>{{ chunk.boundary_context?.[side]?.chunk_id }}</code><p>{{ chunk.boundary_context?.[side]?.text }}</p></article></details></details></div><details v-if="result.evidence_chunks?.length"><summary>Evidence · все чанки, разрешённые для цитирования</summary><article v-for="evidence in result.evidence_chunks" :key="evidence.chunk_id" class="citation"><b>{{ evidence.source }} · {{ evidence.section }}</b><code>{{ evidence.chunk_id }}</code><span class="badge">{{ evidenceLabel(evidence) }}</span><details><summary>Текст evidence</summary><p class="answer-text">{{ evidence.text }}</p></details></article></details><pre>{{ JSON.stringify(result.validation,null,2) }}</pre></details><details v-if="result.messages?.length"><summary>Реальный запрос к модели и verifier</summary><pre>{{ JSON.stringify({generation_messages:result.messages,verifier_messages:result.verifier_messages,usage:result.usage},null,2) }}</pre></details></article></template>
